const err = $input.first().json;

const workflowName  = err.workflow?.name || 'Unknown Workflow';
const nodeName      = err.execution?.lastNodeExecuted || 'Unknown Node';
const errorMessage  = err.execution?.error?.message || 'No message';
const executionId   = err.execution?.id || 'N/A';
const timestamp     = new Date().toLocaleString('en-US', { timeZone: 'Europe/Tallinn' });

let severity  = '⚠️ WARNING';
let action    = 'Check manually';

if (errorMessage.includes('IP_BANNED_418')) {
  severity = '🔴 CRITICAL';
  action   = 'STOP ALL WORKFLOWS NOW! IP is banned.';
} else if (errorMessage.includes('RATE_LIMIT_429')) {
  severity = '🟠 HIGH';
  action   = 'Pause 60 seconds, then resume. Reduce request frequency.';
} else if (errorMessage.includes('INVALID_SIGNATURE') || errorMessage.includes('-1022')) {
  severity = '🔴 CRITICAL';
  action   = 'API key signature invalid — check timestamp synchronization!';
} else if (errorMessage.includes('BALANCE_NOT_SUFFICIENT') || errorMessage.includes('-2018')) {
  severity = '🟠 HIGH';
  action   = 'Insufficient balance! Add USDT or reduce position size.';
} else if (errorMessage.includes('BINANCE_SERVER_ERROR_5')) {
  severity = '🟡 LOW';
  action   = 'Binance server error — wait 30s and retry.';
}

const n8nHost    = 'https://n8n1.thorinvest.org';
const execUrl    = `${n8nHost}/execution/${executionId}`;

const message = [
  `${severity}`,
  ``,
  `*Workflow:* ${workflowName}`,
  `*Node:* ${nodeName}`,
  `*Error:* \`${errorMessage.substring(0, 200)}\``,
  ``,
  `*🕐 Time:* ${timestamp}`,
  `*🆔 Execution ID:* ${executionId}`,
  ``,
  `*🔧 Action:* ${action}`,
  ``,
  `[🔗 View in n8n](${execUrl})`
].join('\n');

return [{ message, severity, workflowName, errorMessage, executionId, timestamp }];
